static GUID WrapperHgToNvGUID(const GUID& in) {
    for (int i = 0; i < g_hgNvGUIDMapCount; i++) {
        const HGGUID& hg = g_hgNvGUIDMap[i].hg;
        if (in.Data1 == hg.Data1 && in.Data2 == hg.Data2 && in.Data3 == hg.Data3
            && memcmp(in.Data4, hg.Data4, 8) == 0) {
            return g_hgNvGUIDMap[i].nv;
        }
    }
    return in;
}

static void WrapperTranslateGUIDArray(GUID* arr, uint32_t count) {
    if (!arr) return;
    for (uint32_t i = 0; i < count; i++) {
        arr[i] = WrapperHgToNvGUID(arr[i]);
    }
}

