typedef uint32_t (*nvidia_encodeRegisterProfileDomain)(const char* domain_name, const char** function_list, uint32_t function_number);
typedef uint8_t (*nvidia_encodeIsProfileCallbackEnabled)(uint32_t domain, uint32_t callback_id);
typedef void (*nvidia_encodeProfileCallbackBegin)(uint32_t domain, uint32_t callback_id);
typedef void (*nvidia_encodeProfileCallbackEnd)(uint32_t domain, uint32_t callback_id);

struct nvidia_encodeProfileHandler {
    nvidia_encodeRegisterProfileDomain registerProfileDomain;
    nvidia_encodeIsProfileCallbackEnabled isCallbackEnabled;
    nvidia_encodeProfileCallbackBegin profileCallbackBegin;
    nvidia_encodeProfileCallbackEnd profileCallbackEnd;
};

static nvidia_encodeProfileHandler g_profileHandler;
static bool gDirectReturn = false;
static const char* gLibName = "nvidia-encode";

static void InitializeProfileHandler() {
    // get library patch
    const char* profile_tool_library = getenv("WRAPPER_INJECTION_PATH");
    if (profile_tool_library == NULL) {
        return;
    }

    // open profile library
    void* tool_handler = dlopen(profile_tool_library, RTLD_LAZY);
    if (!tool_handler) {
        printf("cannot open the file:%s  with error %s\n", profile_tool_library, dlerror());
        return;
    }

    // init profile handler
    g_profileHandler.registerProfileDomain = reinterpret_cast<nvidia_encodeRegisterProfileDomain>(dlsym(tool_handler, "wrapperRegisterProfileDomain"));
    g_profileHandler.isCallbackEnabled = reinterpret_cast<nvidia_encodeIsProfileCallbackEnabled>(dlsym(tool_handler, "wrapperIsProfileCallbackEnabled"));
    g_profileHandler.profileCallbackBegin = reinterpret_cast<nvidia_encodeProfileCallbackBegin>(dlsym(tool_handler, "wrapperProfileCallbackBegin"));
    g_profileHandler.profileCallbackEnd = reinterpret_cast<nvidia_encodeProfileCallbackEnd>(dlsym(tool_handler, "wrapperProfileCallbackEnd"));

    // register profile domain
    if (g_profileHandler.registerProfileDomain != NULL) {
        g_profileDomain = g_profileHandler.registerProfileDomain(gLibName, g_profileFunctionList, sizeof(g_profileFunctionList) / sizeof(g_profileFunctionList[0]));
        if (g_profileDomain == 0) {
            g_profileHandler.isCallbackEnabled = NULL;
        }
    }
}
